const centers = Array.from({ length: COUNT }, (_, step) => {
  if (horizontal) {
    const gap = (width - boxWidth * COUNT) / (COUNT - 1);
    return { x: boxWidth / 2 + step * (boxWidth + gap), y: height / 2 };
  }
  const gap = (height - boxHeight * COUNT) / (COUNT - 1);
  return { x: width / 2, y: boxHeight / 2 + step * (boxHeight + gap) };
});
