ctx.root.append(host);
const svg = svgElement("svg", { class: "mo-f-diagram", viewBox: "0 0 " + width + " " + height });
const nodes = centers.map((center, step) => {
  const group = svgElement("g", {});
  group.append(
    svgElement("rect", {
      class: "mo-f-box",
      x: center.x - boxWidth / 2,
      y: center.y - boxHeight / 2,
      width: boxWidth,
      height: boxHeight,
      rx: 28,
    }),
  );
  const step_label = svgElement("text", { class: "mo-f-step", x: center.x, y: center.y - boxHeight * 0.28 });
  step_label.textContent = "0" + (step + 1);
